static lstr L11138 = {0, 5801, "// std/async/net: TCP sockets on the loop of the thread (SPEC.md section 8, D109).\012//\012// listen and localPort do not suspend. accept, connect, read and write wait in\012// the loop until the socket is ready, so the other tasks run meanwhile. A\012// Listener or a Connection is a handle: copies share the socket, and it\012// closes when the last copy is dropped. host is a numeric IPv4 or IPv6\012// address; there is no name lookup.\012\012import * as Bytes from \"std/bytes\"\012import * as Handles from \"std/internal/asyncio\"\012import { AsyncError } from \"std/async\"\012\012export opaque struct Listener {\012  handle: Handle\012}\012\012export opaque struct Connection {\012  handle: Handle\012}\012\012function failWith(code: int): AsyncError uses alloc {\012  return AsyncError.Failed(Handles.message(code))\012}\012\012// The error of a wait that ended with ready: None when the socket is ready.\012// Each suspending function waits itself, never through a helper task, so a\012// cancel of the task that awaits it reaches the wait. One task at a time may\012// wait in each direction; busy names what the other task already does.\012function checkWait(ready: int, busy: string): Option<AsyncError> uses alloc {\012  if (ready < 0) {\012    return Some(AsyncError.Cancelled)\012  }\012  if (Handles.busy(ready)) {\012    return Some(AsyncError.Failed(`another task is already ${busy}`))\012  }\012  if (ready > 0) {\012    return Some(failWith(ready))\012  }\012  return None\012}\012\012// A socket that accepts connections on host and port. Port 0 picks a free\012// port, which localPort gives.\012export function listen(host: string, port: int): Result<Listener, AsyncError> uses io, alloc {\012  const handle = Handles.listen(host, port)\012  const code = Handles.error()\012  if (code != 0) {\012    return Err(failWith(code))\012  }\012  return Ok(Listener { handle })\012}\012\012// The port the listener is bound to.\012export function localPort(listener: Listener): int uses io {\012  return Handles.localPort(listener.handle)\012}\012\012// The next connection to the listener.\012export async function accept(listener: Listener): Result<Connection, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const handle = Handles.accept(listener.handle)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(Connection { handle })\012    }\012    // A connection that went before it was taken leaves the others to accept.\012    if (!Handles.acceptAgain(code)) {\012      if (!Handles.retry(code)) {\012        return Err(failWith(code))\012      }\012      const problem = checkWait(\012        await Handles.wait(listener.handle, false),\012        \"accepting on this listener\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012}\012\012// A connection to host and port.\012export async function connect(\012  host: string,\012  port: int,\012): Result<Connection, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const handle = Handles.connect(host, port)\012  const code = Handles.error()\012  if (code == 0) {\012    return Ok(Connection { handle })\012  }\012  if (!Handles.pending(code)) {\012    return Err(failWith(code))\012  }\012  const problem = checkWait(await Handles.wait(handle, true), \"connecting this socket\")\012  if (problem is Some(error)) {\012    return Err(error)\012  }\012  const result = Handles.connected(handle)\012  if (result != 0) {\012    return Err(failWith(result))\012  }\012  return Ok(Connection { handle })\012}\012\012// Up to maxBytes bytes from the connection, at most 64 KiB, once some are\012// there. Empty bytes mean the peer has closed its side; a maxBytes of zero or\012// less gives empty bytes at once.\012export async function read(\012  connection: Connection,\012  maxBytes: int,\012): Result<bytes, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const data = Handles.read(connection.handle, maxBytes)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(data)\012    }\012    if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    }\012    const problem = checkWait(\012      await Handles.wait(connection.handle, false),\012      \"reading this connection\",\012    )\012    if (problem is Some(error)) {\012      return Err(error)\012    }\012  }\012}\012\012// The reads of the connection as a stream: Ok(chunk) for each read of up to\012// maxBytes bytes, until the peer closes its side. An error gives one Err, and\012// then the stream ends, so a reader can tell the end from a failure. A\012// maxBytes of zero or less ends the stream at once, as read gives empty bytes.\012export async function* chunks(\012  connection: Connection,\012  maxBytes: int,\012): AsyncGenerator<Result<bytes, AsyncError>> uses (io, alloc) {\012  while (true) {\012    const result = await read(connection, maxBytes)\012    if (result is Ok(chunk)) {\012      if (Bytes.length(chunk) == 0) {\012        return\012      }\012      yield Ok(chunk)\012    } else {\012      yield result\012      return\012    }\012  }\012}\012\012// Writes every byte of data and gives the count. A cancel while it waits\012// ends it with Err(AsyncError.Cancelled), whatever part was sent.\012export async function write(\012  connection: Connection,\012  data: bytes,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  let sent = 0\012  const total = Bytes.length(data)\012  // A wait that a cancel ends gives -1, so the loop needs no second check.\012  while (sent < total) {\012    const count = Handles.write(connection.handle, data, sent)\012    const code = Handles.error()\012    if (code == 0) {\012      sent += count\012    } else if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    } else {\012      const problem = checkWait(\012        await Handles.wait(connection.handle, true),\012        \"writing this connection\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012  return Ok(sent)\012}\012"};
