static lstr L11140 = {0, 863, "// std/async/time: sleep on the loop of the thread (SPEC.md section 8, D109).\012//\012// sleep suspends the running task until the duration has passed; the other\012// tasks of the loop run meanwhile. Time.sleep of std/time blocks the loop.\012\012import * as Tasks from \"std/internal/async\"\012import * as Time from \"std/time\"\012import { Duration } from \"std/time\"\012import { AsyncError } from \"std/async\"\012\012// Waits for duration and gives the time slept, or Err(AsyncError.Cancelled)\012// at once when the task is cancelled, before or while it waits. At exit, the\012// first sleep wakes with Err and the next one drops the task.\012export async function sleep(duration: Duration): Result<Duration, AsyncError> uses io, alloc {\012  const slept = await Tasks.sleep(Time.asNanoseconds(duration))\012  if (slept < 0) {\012    return Err(AsyncError.Cancelled)\012  }\012  return Ok(Time.nanoseconds(slept))\012}\012"};
