static lstr L11160 = {0, 231, "// std/string: searching. The rest of the functions are built into the compiler.\012\012import * as Str from \"std/string\"\012\012export function find(text: string, needle: string): Option<int> uses alloc {\012  return Str.indexOf(text, needle)\012}\012"};
static lstr L11161 = {0, 14, "std/fixedarray"};
static lstr L11162 = {0, 425, "// std/fixedarray: helpers over FixedArray. An index written as values[i] must be\012// proven in range; get checks the index and returns None outside it.\012\012export function get<T, const N: int>(values: FixedArray<T, N>, index: int): Option<T> from values {\012  if (index >= 0 && index < N) {\012    return Some(values[index])\012  }\012  return None\012}\012\012export function length<T, const N: int>(_values: FixedArray<T, N>): int {\012  return N\012}\012"};
static lstr L11163 = {0, 8, "std/hash"};
static lstr L11164 = {0, 670, "// std/hash: hashing. `of` is the hash of a Hashable value and may change between builds.\012// `fnv1a` is FNV-1a 64 over the UTF-8 bytes of a string and never changes.\012\012import * as Str from \"std/string\"\012import * as U64 from \"std/u64\"\012import * as Ranges from \"std/range\"\012\012const FNV_OFFSET: u64 = 14695981039346656037\012const FNV_PRIME: u64 = 1099511628211\012\012export function of<T: Hashable>(value: T): int {\012  return Hashable.hash(value)\012}\012\012export function fnv1a(text: string): u64 {\012  let state = FNV_OFFSET\012  const length = Str.length(text)\012  for (const index of Ranges.upTo(length)) {\012    state = (state ^ U64.wrap(Str.byteAt(text, index))) * FNV_PRIME\012  }\012  return state\012}\012"};
